{
  "technical_and_design_decisions": [
    "Use existing Spring Cloud Data Flow (s-c-d) and Spring Cloud Stream (s-c-s) codebases, build tools, and testing stacks (JUnit, Mockito, Spring Test).",
    "For U8, implement a named binder connection factory registry that allows per-binding binder selection via configuration while keeping backward compatibility with a default binder.",
    "For U7, correct the stream/container lifecycle state machine and Admin UI REST invocation so shutdown propagates for streams using jdbc and hdfs modules.",
    "For U2-U6, extend the current SPI test harness with mocked or lightweight embedded deployer environments to validate integration and unit behaviors in CI.",
    "Documentation for BOM templates (U1) will be written in AsciiDoc within the project documentation module, including reusable examples."
  ],
  "assumptions": [
    "s-c-d means Spring Cloud Data Flow and s-c-s means Spring Cloud Stream.",
    "{{Lattice}}, {{CC}}, and {{YARN}} refer to existing deployer SPI implementations (Lattice, Cloud Foundry/CC, Hadoop YARN).",
    "The developer already has a configured environment and CI access; only minor CI verification is needed.",
    "BOM templates refer to Maven Bill of Materials used to dynamically manage external library versions.",
    "New tests placed in standard test directories will be executed automatically by the existing CI pipeline.",
    "Effort estimates cover a single experienced developer's implementation work and exclude external reviews, meetings, and release overhead.",
    "The U7 bug can be fixed without changes to external systems and can be validated with an in-memory or mocked JDBC source."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Document BOM templates usage",
      "activity_description": "Author reference documentation explaining BOM templates and dynamic inclusion of external libraries, with examples (U1).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Integration tests for Lattice SPI",
      "activity_description": "Develop integration test suite exercising Lattice SPI deployment lifecycle, wired to run in CI (U2).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Integration tests for CC SPI",
      "activity_description": "Develop integration test suite for CC (Cloud Foundry) SPI covering core scenarios, run via CI (U3).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Integration tests for YARN SPI",
      "activity_description": "Develop integration test suite for YARN SPI covering deployment and runtime, run via CI (U4).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Unit tests for Lattice SPI",
      "activity_description": "Add unit tests with mocks for Lattice SPI components to increase coverage (U5).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Unit tests for YARN SPI",
      "activity_description": "Add unit tests with mocks for YARN SPI components to increase coverage (U6).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Fix container shutdown from Admin UI",
      "activity_description": "Investigate and fix inability to shut down container for stream with jdbc|hdfs; add regression test and verify UI behavior (U7).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Design multiple binder connection factory support",
      "activity_description": "Design configuration model and API for multiple binder connection factories in Spring Cloud Stream (U8).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Implement multiple binder connection factory support",
      "activity_description": "Code the binder factory registry, configuration binding, and integration with the binding process (U8).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Test multiple binder connection factory support",
      "activity_description": "Write unit and integration tests verifying mixed consume/publish across binders and update related docs (U8).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "CI verification and documentation publishing",
      "activity_description": "Verify all new tests execute in CI pipeline, publish documentation, and perform final local build verification.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 144
  }
}

